def length_of_longest_substring(s):
    left = 0
    seen = {}
    best = 0
    for right, ch in enumerate(s):
        if ch in seen and seen[ch] >= left:
            left = seen[ch] + 1
        seen[ch] = right
        best = max(best, right - left + 1)
    return best

def average(nums):
    if not nums:
        return 0
    return sum(nums) / len(nums)

def is_valid_brackets(text):
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in text:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
        else:
            return False
    return not stack

def binary_search(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def deduplicate(items):
    seen = set()
    result = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def factorial(n):
    if n < 0:
        return None
    result = 1
    for value in range(2, n + 1):
        result *= value
    return result

def two_sum(nums, target):
    seen = {}
    for index, value in enumerate(nums):
        need = target - value
        if need in seen:
            return [seen[need], index]
        seen[value] = index
    return []

def is_palindrome(text):
    left, right = 0, len(text) - 1
    while left < right:
        if text[left] != text[right]:
            return False
        left += 1
        right -= 1
    return True

def fibonacci(n):
    if n < 0:
        return None
    if n < 2:
        return n
    first, second = 0, 1
    for _ in range(2, n + 1):
        first, second = second, first + second
    return second

def count_words(text):
    counts = {}
    for word in text.split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def flatten(items):
    result = []
    for item in items:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def find_max(nums):
    if not nums:
        return None
    current = nums[0]
    for value in nums[1:]:
        if value > current:
            current = value
    return current

def find_min(nums):
    if not nums:
        return None
    current = nums[0]
    for value in nums[1:]:
        if value < current:
            current = value
    return current

def total(nums):
    result = 0
    for value in nums:
        result += value
    return result

def is_prime(n):
    if n < 2:
        return False
    divisor = 2
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 1
    return True

def count_vowels(text):
    vowels = set('aeiouAEIOU')
    return sum(1 for ch in text if ch in vowels)

def second_largest(nums):
    unique = sorted(set(nums))
    if len(unique) < 2:
        return None
    return unique[-2]

def common_prefix(left, right):
    result = []
    for a, b in zip(left, right):
        if a != b:
            break
        result.append(a)
    return ''.join(result)

def char_counts(text):
    counts = {}
    for ch in text:
        counts[ch] = counts.get(ch, 0) + 1
    return counts

def missing_number(nums):
    expected = len(nums) * (len(nums) + 1) // 2
    return expected - sum(nums)
